Unstable Flat Check.command:
// DEPRECATED, this macro has been replaced by the Legacy but Improved Unstable DC setting in Inventors+ settings!
// Constants
const maxDC = 17;
const minDC = 9;
const perUnstable = 4;

// Logic
if (!actor) {
  return ui.notifications.error("PF2E.ErrorMessage.NoTokenSelected", {
    localize: true,
  });
}

const unstableActionCount = Math.max(0,
  actor.itemTypes.action.filter(x => x.system.traits.value.includes("unstable")).length
  + actor.itemTypes.feat.filter(x => x.system.traits.value.includes("unstable")).length
  - 1);

const defaultDC = Math.max(minDC, maxDC - unstableActionCount * perUnstable);
const defaultActions = actor.getFlag("pf2e", "inventorsPlus.unstableActions") || 0;

const content = `<form>
  <body>
      <section>
          <h1>Roll Unstable Check</h1>
      </section>
      <div class="form-group">
          <label for="unstableDc">Your Unstable DC is</label>
          <strong id="unstableDc">${defaultDC}</strong>
      </div>
      <div class="form-group">
          <label for="unstableActions">Unstable Action Successes</label>
          <input type="number" id="unstableActions" value="${defaultActions}" placeholder="0" min=0 step=1>
      </div>
  </body>
  </form>`;

await Dialog.wait({
  title: "Roll Unstable Check",
  content,
  buttons: {
    create: {
      label: "Roll",
      icon: "<i class='fa-solid fa-dice-d20'></i>",
      callback: async ([html]) => {
        const DC = Number(html.querySelector("#unstableDc").innerHTML);
        actor.setFlag("pf2e", "inventorsPlus.unstableActions", Number(html.querySelector("#unstableActions").value));

        new actor.perception.constructor(actor, {
          slug: 'flat',
          label: `Unstable Flat Check`,
          check: { type: 'flat-check' },
      }).roll({
          dc: {
            value: DC,
            visible: true
          },
          actor,
          token,
          showDC: "all",
      });

        return {};
      },
    },
    cancel: {
      label: "Exit",
      icon: "<i class='fa-solid fa-ban'></i>",
      callback: (_html) => {
        return {};
      },
    },
  },
  render: ([html]) => {
    html.querySelector("#unstableActions").addEventListener("change", (event) => {
      const extraDC = event.target.value * perUnstable;
      $(event.target).parent().parent().find("[id=unstableDc]").html(Math.min(maxDC, defaultDC + extraDC));
    })
  },
  close: (_html) => {
    return {};
  }
});
